name: Claude Code Review
on:
  issues:
    types: [opened]
  issue_comment:
    types: [created]

jobs:
  claude-review:
    if: |
      github.event_name == 'issues' || 
      (github.event_name == 'issue_comment' && 
       (contains(github.event.comment.body, '@claude') || 
        contains(github.event.issue.title, '@claude')))
    runs-on: ubuntu-latest
    steps:
      - name: Check collaborator status
        id: check-collaborator
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const sender = context.payload.sender.login;

            try {
              const response = await github.rest.repos.getCollaboratorPermissionLevel({
                owner: owner,
                repo: repo,
                username: sender
              });

              const permission = response.data.permission;
              if (permission === 'admin' || permission === 'maintain' || permission === 'write') {
                return true;
              } else {
                return false;
              }
            } catch (error) {
              // If we can't determine collaboration status, don't proceed
              return false;
            }

      - name: Claude Code Review
        if: steps.check-collaborator.outputs.result == 'true'
        uses: anthropic-ai/claude-code-review@v1
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
